688		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
689		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
690		\begin{enumerate}
691			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
692			      \begin{equation}\label{eq:pauli-product-power}
693				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
694				      \qquad \text{and} \qquad
695				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
696			      \end{equation}
697			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
698			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
699			      $p$-th roots of unity.
700			\item For all $a, b \in \F_q^n$,
701			      % Paper equation label kept on the display it names.
702			      \begin{equation}\label{eq:twisted-fq}
703				      \tau^X(a)\, \tau^Z(b)
704				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
705			      \end{equation}
706			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
707			      $q = p$, $n = 1$ reads
708			      \begin{equation}\label{eq:twisted-fp}
709				      \sigma^X(a)\, \sigma^Z(b)
710				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
711				      \qquad \text{for all } a, b \in \F_p\;.
712			      \end{equation}
713		\end{enumerate}
714	\end{lemma}
715	\begin{proof}
716		\leanok
717		\uses{def:generalized-pauli, def:subfield-trace}
718		All identities are verified on computational basis states. For the product
719		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
720		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
721		combine by $\F_q$-linearity of the trace, and the power relation follows by
722		iterating. For the scalar twisted commutation,
723		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
724		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
725		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
726		follows by applying the scalar relation factor by factor and summing the
727		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
728		trace is the identity map, which gives \eqref{eq:twisted-fp}.
